const initialProducts = [
  { id: 1, name: 'Laptop', price: 999 },
  { id: 2, name: 'Phone', price: 699 },
  { id: 3, name: 'Tablet', price: 499 },
  { id: 4, name: 'Headphones', price: 199 },
  { id: 5, name: 'Watch', price: 299 },
]

let products = initialProducts
let syncRevision = 0

export async function getAllProducts() {
  await new Promise((resolve) => setTimeout(resolve, 100))
  return products.map((p) => ({ ...p, syncRevision }))
}

export async function syncProducts() {
  syncRevision += 1
  await new Promise((resolve) => setTimeout(resolve, 2000))
  products = products.map((p) => ({
    ...p,
    price: p.price + 1,
  }))
  return products
}

import { unstable_cache, revalidateTag } from 'next/cache'
import { getAllProducts, syncProducts } from '@/lib/db'

const getCachedProducts = unstable_cache(
  async () => getAllProducts(),
  ['products-list'],
  { tags: ['products'] },
)

async function syncCatalog() {
  'use server'
  syncProducts()
    .then(() => {
      revalidateTag('products')
    })
    .catch((err) => {
      console.error('Catalog sync failed:', err)
    })
}

export default async function AdminCatalogPage() {
  const products = await getCachedProducts()

  return (
    <main>
      <header>
        <h1>Product Catalog</h1>
        <form action={syncCatalog}>
          <button type="submit">Sync latest catalog</button>
        </form>
      </header>
      <ul>
        {products.map((product) => (
          <li key={product.id}>
            <span>{product.name}</span>
            <span>${product.price}</span>
          </li>
        ))}
      </ul>
    </main>
  )
}

